    'SELECT embedding FROM memory_embeddings WHERE entry_id = ?'
  );
  const embeddingRow = embeddingStmt.get(row.id) as any;  // ← N+1: one extra query per row
```

`query()` at line 445 calls `rows.map(row => this.rowToEntry(row))` — N returned rows = N extra embedding queries. The `get()` (line 229) and `getByKey()` (line 246) each also call `rowToEntry`.

**Fix**: Join the tables in the base query:

```typescript
// BEFORE: separate query per row
private rowToEntry(row: any): MemoryEntry {
  const embeddingStmt = this.db!.prepare(
    'SELECT embedding FROM memory_embeddings WHERE entry_id = ?'
  );
  const embeddingRow = embeddingStmt.get(row.id) as any;
  // ...
}

// AFTER: JOIN once in the caller's query
// In query():
const sql = `
  SELECT e.*, emb.embedding 
  FROM memory_entries e
  LEFT JOIN memory_embeddings emb ON emb.entry_id = e.id
  WHERE 1=1
`;
// Now row.embedding is already populated — no extra per-row query needed
```

Or simpler — just make `rowToEntry` check if embedding is already joined:

```typescript
private rowToEntry(row: any): MemoryEntry {
  let embedding: Float32Array | undefined;

  // Embedding may already be joined (LEFT JOIN) or fetched separately
  if (row.embedding) {
    embedding = new Float32Array(row.embedding.buffer);
  } else if (row.id) {
    // Fallback for callers that haven't been migrated to JOIN yet
    const embeddingStmt = this.db!.prepare(
      'SELECT embedding FROM memory_embeddings WHERE entry_id = ?'
    );
    const embeddingRow = embeddingStmt.get(row.id) as any;
    if (embeddingRow?.embedding) {
      embedding = new Float32Array(embeddingRow.embedding.buffer);
    }
  }
  // ...
}
```

Then update `query()` to use `LEFT JOIN` — eliminating the N+1 entirely for the critical path.

### 🟡 Medium — `JsonBackend.getByKey()` linear scan

**File**: `v3/@claude-flow/memory/src/database-provider.ts:441-448`

```typescript
async getByKey(namespace: string, key: string): Promise<MemoryEntry | null> {
  for (const entry of this.entries.values()) {  // O(n) — full scan
    if (entry.namespace === namespace && entry.key === key) {
      return entry;
    }
  }
  return null;
}
```

**Fix**: Maintain a secondary index Map:

```typescript
private namespaceKeyIndex = new Map<string, string>(); // "ns:key" → entryId

async store(entry: MemoryEntry): Promise<void> {
  this.entries.set(entry.id, entry);
  this.namespaceKeyIndex.set(`${entry.namespace}:${entry.key}`, entry.id);
  await this.persist();
}

async getByKey(namespace: string, key: string): Promise<MemoryEntry | null> {
  const id = this.namespaceKeyIndex.get(`${namespace}:${key}`);
  return id ? this.entries.get(id) || null : null;  // O(1)
}
```

### 🟡 Medium — `JsonBackend.search()` brute-force O(n)

**File**: `v3/@claude-flow/memory/src/database-provider.ts:484-498`

```typescript
async search(embedding: Float32Array, options: SearchOptions): Promise<SearchResult[]> {
  for (const entry of this.entries.values()) {    // FULL SCAN
    if (!entry.embedding) continue;
    const similarity = this.cosineSimilarity(embedding, entry.embedding);
    // ...
  }
}
```

The SQLite backend at line 464 returns `[]` with a warning to use `HybridBackend`. But the JSON backend actually computes it — O(n) full-scan with cosine similarity on every entry. This should either be removed (delegate to HybridBackend) or use the HNSW index from the upper layer.

---

## Final Combined Scorecard

| # | Issue | Category | Severity | Effort | Type |
|---|-------|----------|----------|--------|------|
| 1 | `rowToEntry()` N+1 embedding query | N+1 | 🔴 **Critical** | Low | Backend |
| 2 | Monolithic Index.tsx (1655 lines) | Re-renders | 🔴 High | Medium | Frontend |
| 3 | AgentStep timer leak | Memory | 🔴 High | Low | Frontend |
| 4 | Carousel listener leak | Memory | 🔴 High | Low | Frontend |
| 5 | `[toast]` dep re-run loop | Re-renders | 🟡 Medium | Low | Frontend |
| 6 | No `React.memo` anywhere | Re-renders | 🟡 Medium | Low | Frontend |
| 7 | QueryClient staleTime=0 | Caching | 🟡 Medium | Low | Frontend |
| 8 | AJV recompilation per tool call | Redundant | 🟡 Medium | Low | Backend |
| 9 | `JsonBackend.getByKey()` O(n) scan | N+1 | 🟡 Medium | Low | Backend |
| 10 | `JsonBackend.search()` brute-force O(n) | N+1 | 🟡 Medium | Medium | Backend |
| 11 | No `executeResearch` AbortController | Memory | 🟡 Medium | Medium | Frontend |
| 12 | Triple array scan for stats | Redundant | 🟢 Low | Low | Frontend |
| 13 | Inline style objects | Re-renders | 🟢 Low | Low | Frontend |
| 14 | Scroll timeout leaks | Memory | 🟢 Low | Low | Frontend |
| 15 | Debug console.log | Memory | 🟢 Low | Low | Frontend |
| 16 | `JSON.stringify` in dep array | Memory | 🟢 Low | Low | Frontend |
| 17 | Compact JSON in tool output | Caching | 🟢 Low | Low | Backend |
| 18 | Sequential init connections | N+1 | 🟢 Low | Low | Backend |

The **top 3 highest-impact fixes** are:
1. **`rowToEntry()` LEFT JOIN** — eliminate the N+1 across all query paths
2. **AgentStep timer cleanup** — stop state-updates-on-unmounted leaking per step transition
3. **QueryClient staleTime** — stop every mount from refetching

